<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref } from 'vue'
import { X, ArrowUpRight, CalendarPlus, MapPin, Heart, Send, Copy, Check } from 'lucide-vue-next'
import { wedding as w, stops, type StopId } from '../data/wedding'
import { save } from '../state'
const props = defineProps<{ id: StopId; guest: string }>()
const emit = defineEmits<{ close: [] }>()
const title = computed(() => stops.find(s => s.id === props.id)!)
const heading = ref<HTMLElement>(), name = ref(props.guest === 'Tamu Istimewa' ? '' : props.guest), attendance = ref('hadir'), count = ref(1), message = ref(''), saved = ref(false), copied = ref(false), error = ref('')
const now = ref(Date.now()); const timer = setInterval(() => now.value = Date.now(), 1000)
const days = computed(() => Math.max(0, Math.ceil((new Date(`${w.date}T${w.ceremony.start}:00${w.offset}`).getTime() - now.value) / 86400000)))
const whatsappLink = computed(() => `https://wa.me/${w.whatsapp}?text=${encodeURIComponent(`Halo ${w.bride.short} & ${w.groom.short}, saya ${name.value}. ${attendance.value === 'hadir' ? `Insyaallah hadir (${count.value} orang)` : attendance.value === 'tidak' ? 'Mohon maaf belum bisa hadir' : 'Saya belum bisa memastikan kehadiran'}.\n${message.value}`)}`)
function submit() { save('rsvp', { name: name.value, attendance: attendance.value, count: attendance.value === 'hadir' ? count.value : 0, message: message.value }); saved.value = true }
async function copy() { try { await navigator.clipboard.writeText(w.gift.number); copied.value = true; error.value = '' } catch { error.value = 'Salin nomor rekening yang tertera secara manual.' } }
function calendar() {
  const start = new Date(`${w.date}T${w.ceremony.start}:00${w.offset}`).toISOString().replace(/[-:]/g, '').replace('.000', '')
  const end = new Date(`${w.date}T${w.reception.end}:00${w.offset}`).toISOString().replace(/[-:]/g, '').replace('.000', '')
  const escape = (s: string) => s.replace(/\\/g, '\\\\').replace(/\n/g, '\\n').replace(/,/g, '\\,').replace(/;/g, '\\;')
  const stamp = new Date().toISOString().replace(/[-:]/g, '').replace('.000', '')
  const data = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Janji Sepixel//Undangan//ID', 'BEGIN:VEVENT', `UID:${w.date}-aruna-bima@janji-sepixel.local`, `DTSTAMP:${stamp}`, `DTSTART:${start}`, `DTEND:${end}`, `SUMMARY:${escape(`Pernikahan ${w.bride.short} & ${w.groom.short}`)}`, `LOCATION:${escape(`${w.venue}, ${w.address}`)}`, 'END:VEVENT', 'END:VCALENDAR'].join('\r\n')
  const url = URL.createObjectURL(new Blob([data], { type: 'text/calendar;charset=utf-8' })); const a = document.createElement('a'); a.href = url; a.download = 'hari-bahagia.ics'; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000)
}
onMounted(() => { heading.value?.focus(); try { const data = JSON.parse(localStorage.getItem('janji-sepixel:rsvp') || 'null'); if (data) { name.value = data.name || name.value; attendance.value = data.attendance || 'hadir'; count.value = data.count || 1; message.value = data.message || '' } } catch { /* optional draft */ } })
onBeforeUnmount(() => clearInterval(timer))
</script>
<template>
  <div class="sheet-header"><span class="eyebrow">{{ title.icon }} &nbsp; UNDANGAN DITEMUKAN</span><button class="round-button" @click="emit('close')" aria-label="Tutup undangan"><X :size="20"/></button></div>
  <div class="sheet-body"><h2 ref="heading" tabindex="-1">{{ title.name }}</h2>
    <template v-if="id === 'welcome'"><div class="letter-stamp">♥</div><p class="eyebrow center">KEPADA YANG TERSAYANG</p><h3 class="guest-name">{{ guest }}</h3><p>Dengan penuh rasa syukur, kami mengundangmu menjadi bagian dari awal petualangan kami sebagai pasangan suami istri.</p><div class="couple-signature">{{ w.bride.short }} <i>&</i> {{ w.groom.short }}</div><p class="center">{{ w.dateLabel }}</p><div class="soft-note">Surat pertama sudah terbuka! Lanjutkan perjalanan ke gazebo untuk mengenal kami, lalu temukan detail hari bahagia di taman ini.</div></template>
    <template v-else-if="id === 'couple'"><p>Dua hati, satu arah. Dengan restu keluarga, kami siap memulai babak baru.</p><div class="couple-card"><img v-if="w.bride.photo" class="couple-photo" :src="w.bride.photo" :alt="w.bride.full"><span v-else class="pixel-avatar bride" aria-hidden="true">♛</span><span class="eyebrow">MEMPELAI WANITA</span><h3>{{ w.bride.full }}</h3><p>{{ w.bride.role }} dari<br>{{ w.bride.parents }}</p></div><div class="ampersand">&</div><div class="couple-card"><img v-if="w.groom.photo" class="couple-photo" :src="w.groom.photo" :alt="w.groom.full"><span v-else class="pixel-avatar groom" aria-hidden="true">♜</span><span class="eyebrow">MEMPELAI PRIA</span><h3>{{ w.groom.full }}</h3><p>{{ w.groom.role }} dari<br>{{ w.groom.parents }}</p></div></template>
    <template v-else-if="id === 'event'"><p>Mari bertemu di hari yang akan selalu kami kenang.</p><div class="countdown"><strong>{{ days }}</strong><span>{{ days ? 'hari menuju hari bahagia' : 'Hari bahagia telah tiba' }}</span></div><h3>{{ w.dateLabel }}</h3><div v-for="item in [w.ceremony, w.reception]" :key="item.label" class="event-card"><span class="event-icon">✦</span><div><h3>{{ item.label }}</h3><p>{{ item.start.replace(':', '.') }} – {{ item.end.replace(':', '.') }} WIB</p><small>{{ w.venue }}</small></div></div><button class="primary full" @click="calendar"><CalendarPlus :size="17"/> Simpan ke kalender</button><p class="fine-print">Jadwal dan tempat merupakan data contoh.</p></template>
    <template v-else-if="id === 'location'"><div class="venue-art"><span>⚑</span><small>DI SINILAH KITA BERTEMU</small></div><h3>{{ w.venue }}</h3><p><MapPin :size="15"/> {{ w.address }}</p><div class="soft-note">{{ w.venueNote }} Tautan peta saat ini menunjukkan kota Bandung.</div><a class="primary full" :href="w.mapsUrl" target="_blank" rel="noopener noreferrer">Buka Google Maps <ArrowUpRight :size="17"/></a></template>
    <template v-else-if="id === 'story'"><p>Setiap kisah punya titik awal. Ini beberapa checkpoint dalam perjalanan kami.</p><div class="story-timeline"><section v-for="item in w.story" :key="item.year"><span class="eyebrow">{{ item.year }}</span><h3>{{ item.title }}</h3><p>{{ item.text }}</p></section></div><p class="eyebrow">ALBUM KENANGAN</p><div class="memory-grid"><div v-for="(photo, index) in w.gallery" :key="index" class="memory" :class="`memory-${index}`"><img v-if="photo.src" :src="photo.src" :alt="photo.caption" loading="lazy"><div v-else aria-hidden="true">{{ ['✿', '☀', '♥'][index % 3] }}</div><span>{{ photo.caption }}</span></div></div><p class="fine-print">Foto pasangan ilustratif untuk undangan demo.</p></template>
    <template v-else-if="id === 'rsvp'"><p>Kehadiran dan doamu adalah bagian terindah dari hari kami.</p><form v-if="!saved" @submit.prevent="submit"><label>Nama tamu<input v-model="name" required maxlength="100" autocomplete="name" placeholder="Nama lengkapmu"></label><label>Apakah kamu akan hadir?<select v-model="attendance"><option value="hadir">Ya, saya akan hadir</option><option value="tidak">Maaf, belum bisa hadir</option><option value="ragu">Belum dapat memastikan</option></select></label><label v-if="attendance === 'hadir'">Jumlah tamu<select v-model="count"><option v-for="n in 5" :key="n" :value="n">{{ n }} orang</option></select></label><label>Ucapan & doa<textarea v-model="message" rows="3" maxlength="1000" placeholder="Tuliskan doa baik untuk kedua mempelai…"/></label><div class="soft-note">{{ w.whatsapp ? 'Simpan draf, lalu kirim konfirmasi melalui WhatsApp.' : 'Mode contoh: draf tersimpan di perangkat ini. Belum dikirim ke mempelai atau ditampilkan kepada tamu lain.' }}</div><button class="primary full" type="submit"><Heart :size="16"/> Simpan draf konfirmasi</button></form><div v-else class="success-state" role="status"><Check :size="36"/><h3>Drafmu tersimpan, {{ name }}.</h3><p>{{ w.whatsapp ? 'Kirim melalui WhatsApp agar diterima mempelai.' : 'Ini masih demo. Konfirmasi belum dikirim ke mempelai.' }}</p><a v-if="w.whatsapp" class="primary full" :href="whatsappLink" target="_blank" rel="noopener noreferrer"><Send :size="16"/> Kirim lewat WhatsApp</a><button class="secondary full" @click="saved = false">Edit konfirmasi</button></div></template>
    <template v-else><div class="letter-stamp">◇</div><p class="center">Doa dan kehadiranmu adalah hadiah terbaik. Terima kasih telah menjadi bagian dari perjalanan kami.</p><div v-if="w.gift.enabled && w.gift.number" class="gift-card"><span class="eyebrow">{{ w.gift.bank }}</span><h3>{{ w.gift.number }}</h3><p>a.n. {{ w.gift.owner }}</p><button class="primary full" @click="copy"><Copy :size="16"/> {{ copied ? 'Nomor tersalin' : 'Salin nomor rekening' }}</button><p v-if="error" role="status">{{ error }}</p></div><div v-else class="soft-note">Informasi hadiah digital belum diaktifkan. Cukup bawa senyum dan doa terbaikmu.</div></template>
    <p class="sheet-signoff">WITH LOVE, {{ w.bride.short.toUpperCase() }} & {{ w.groom.short.toUpperCase() }} <span>♥</span></p>
  </div><div class="sheet-footer"><button class="secondary full" @click="emit('close')">Kembali ke petualangan <span>↗</span></button></div>
</template>
